//! `levels/ffa_sky.lvl` (generated by `scripts/gen_sky_level.py`): the vertical arena of seven floating buildings. Pinned:
//! the box count stays modest, there is no ground (void under the roofs), every spawn stands on a roof deck and every
//! deck is joined to the others by a walkable route (a new player never needs the grapple to leave), the structures
//! have tall flat faces and real gaps between them, pickups are supported, and the numbers fit the engine.

use shinobi_sim::character::{Cfg, PhysicsWorld};
use shinobi_sim::level::{parse_level_file, LevelBox, LevelFile};
use shinobi_sim::rapier3d::prelude::*;
use shinobi_sim::spawn::far_dist;
use std::collections::{HashSet, VecDeque};

const ROOF: f32 = 56.0;

fn load() -> LevelFile {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa_sky.lvl");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    parse_level_file(&text).unwrap_or_else(|e| panic!("ffa_sky.lvl: {e}"))
}

fn world(l: &LevelFile) -> PhysicsWorld {
    let mut w = PhysicsWorld { bodies: RigidBodySet::new(), colliders: ColliderSet::new(), islands: IslandManager::new(), queries: QueryPipeline::new() };
    l.level.insert_into(&mut w);
    w.queries.update(&w.colliders);
    w
}

fn inside(b: &LevelBox, p: [f32; 3]) -> bool {
    (p[0] - b.center[0]).abs() <= b.half[0] && (p[1] - b.center[1]).abs() <= b.half[1] && (p[2] - b.center[2]).abs() <= b.half[2]
}

/// Top face height of the highest box covering (x, z), if any (the boxes are axis aligned: no ramps here).
fn top_at(l: &LevelFile, x: f32, z: f32) -> Option<f32> {
    l.level
        .boxes
        .iter()
        .filter(|b| (x - b.center[0]).abs() <= b.half[0] && (z - b.center[2]).abs() <= b.half[2])
        .map(|b| b.center[1] + b.half[1])
        .fold(None, |m: Option<f32>, h| Some(m.map_or(h, |m| m.max(h))))
}

fn d2(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

#[test]
fn modest_box_count_with_a_roof_spawn_ring_and_sparse_pickups() {
    let l = load();
    assert!((30..=110).contains(&l.level.boxes.len()), "{} boxes", l.level.boxes.len());
    assert!((10..=14).contains(&l.level.spawns.len()), "{} spawns", l.level.spawns.len());
    assert!((2..=6).contains(&l.pickups.len()), "{} pickups: sparse", l.pickups.len());
    assert!(l.pickups.iter().all(|p| p.respawn_secs >= 10.0));
}

#[test]
fn there_is_no_ground_only_void_under_the_buildings() {
    let l = load();
    let lowest = l.level.boxes.iter().map(|b| b.center[1] - b.half[1]).fold(f32::MAX, f32::min);
    assert!(lowest >= 4.0, "something reaches down to y = {lowest}: the buildings must float (kill plane is -20)");
    assert_eq!(l.level.floor_half(), None, "no floor slab at y = 0");
}

#[test]
fn spawns_stand_on_roofs_clear_of_geometry_and_not_stacked() {
    let l = load();
    let cfg = Cfg::default();
    let reach = cfg.half_height + cfg.radius;
    for s in &l.level.spawns {
        for dy in [-reach + 0.05, -0.3, 0.0, 0.3, reach - 0.05] {
            for (ox, oz) in [(0.0, 0.0), (cfg.radius, 0.0), (-cfg.radius, 0.0), (0.0, cfg.radius), (0.0, -cfg.radius)] {
                let p = [s[0] + ox, s[1] + dy, s[2] + oz];
                assert!(!l.level.boxes.iter().any(|b| inside(b, p)), "spawn {s:?}: capsule point {p:?} is inside geometry");
            }
        }
        let top = top_at(&l, s[0], s[2]).expect("a spawn over void");
        assert!((top - (s[1] - reach)).abs() < 0.1, "spawn {s:?} floats or is buried (surface {top})");
        assert!((top - ROOF).abs() < 0.01, "spawn {s:?} is not on a roof deck (surface {top})");
    }
    let n = l.level.spawns.len();
    let nearest: Vec<f32> = (0..n).map(|i| (0..n).filter(|j| *j != i).map(|j| d2(l.level.spawns[i], l.level.spawns[j])).fold(f32::MAX, f32::min)).collect();
    let min = nearest.iter().copied().fold(f32::MAX, f32::min);
    assert!(min >= 9.0, "two spawns only {min:.1} m apart");
    let max = nearest.iter().copied().fold(0.0, f32::max);
    assert!(max <= 45.0, "a spawn is {max:.1} m from its nearest neighbour: players would wander alone");
    let far = far_dist(&l.level.spawns);
    assert!((20.0..=60.0).contains(&far), "preferred respawn distance {far:.1} m");
}

/// Flood the roof layer (surface height = ROOF, 1 m cells, 4-neighbour): every spawn must be in one component, so a
/// player who spawns anywhere can walk (bridges, no grapple) to any other deck.
#[test]
fn every_spawn_deck_is_joined_to_the_others_by_walkable_bridges() {
    let l = load();
    let half = 64i32;
    let on_deck = |x: i32, z: i32| top_at(&l, x as f32 + 0.5, z as f32 + 0.5).map_or(false, |t| (t - ROOF).abs() < 0.01);
    let cell_of = |p: [f32; 3]| (p[0].floor() as i32, p[2].floor() as i32);
    let start = cell_of(l.level.spawns[0]);
    let mut seen: HashSet<(i32, i32)> = HashSet::new();
    let mut q = VecDeque::from([start]);
    seen.insert(start);
    while let Some((x, z)) = q.pop_front() {
        for (dx, dz) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let c = (x + dx, z + dz);
            if c.0.abs() <= half && c.1.abs() <= half && !seen.contains(&c) && on_deck(c.0, c.1) {
                seen.insert(c);
                q.push_back(c);
            }
        }
    }
    for s in &l.level.spawns {
        assert!(seen.contains(&cell_of(*s)), "spawn {s:?} is on an island with no walkable route to the rest");
    }
    // the bridges are what joins them: removing the walkable cells outside any 4 m wide strip would split the graph; at
    // least 6 distinct bridge boxes (thin, long) exist
    let bridges = l.level.boxes.iter().filter(|b| b.half[1] <= 0.3 && (b.half[0] >= 10.0 || b.half[2] >= 10.0)).count();
    assert!(bridges >= 4, "{bridges} bridges");
}

#[test]
fn structures_have_tall_flat_faces_and_real_void_gaps() {
    let l = load();
    // tall faces: at least five boxes with a face 40 m or more tall (wall-run up and down)
    let tall = l.level.boxes.iter().filter(|b| b.half[1] * 2.0 >= 40.0 && (b.half[0] >= 2.5 || b.half[2] >= 2.5)).count();
    assert!(tall >= 7, "{tall} structures with 40 m faces");
    // gaps: along the line from the centre tower to a corner tower there is open void for 20 m or more
    let steps = 200;
    let mut run = 0.0f32;
    let mut best = 0.0f32;
    for i in 0..=steps {
        let t = i as f32 / steps as f32;
        let p = [10.0 + (41.0 - 10.0) * t, 40.0, 10.0 + (41.0 - 10.0) * t];
        if l.level.boxes.iter().any(|b| inside(b, p)) {
            run = 0.0;
        } else {
            run += 1.0;
            best = best.max(run);
        }
    }
    let gap = best * ((31.0f32 * 2.0f32.sqrt()) / steps as f32);
    assert!(gap >= 20.0, "the diagonal gap between the tower and a corner is only {gap:.1} m (mid height)");
    // roofs are walled by a low lip (0.9 m): jumpable, but it stops a stumble
    assert!(l.level.boxes.iter().filter(|b| (b.center[1] + b.half[1] - (ROOF + 0.9)).abs() < 0.01).count() >= 10, "roof lips");
}

#[test]
fn pickups_are_supported_and_not_inside_geometry() {
    let l = load();
    for p in &l.pickups {
        assert!(!l.level.boxes.iter().any(|b| inside(b, p.pos)), "pickup {:?} is inside geometry", p.pos);
        let top = top_at(&l, p.pos[0], p.pos[2]).unwrap_or(f32::MIN);
        assert!((p.pos[1] - top - 1.0).abs() < 0.3, "pickup {:?} is not ~1 m above a surface (top {top})", p.pos);
    }
}

#[test]
fn engine_numeric_limits_cover_the_map() {
    let l = load();
    let top = l.level.boxes.iter().map(|b| b.center[1] + b.half[1]).fold(0.0, f32::max);
    let far = l.level.boxes.iter().map(|b| b.center[0].abs() + b.half[0]).chain(l.level.boxes.iter().map(|b| b.center[2].abs() + b.half[2])).fold(0.0, f32::max);
    assert!(far <= 64.0, "geometry reaches {far} m sideways");
    assert!((80.0..=100.0).contains(&top), "tallest geometry {top} m");
    let q = shinobi_proto::quant::q_pos3([2.0 * far, top, 2.0 * far]);
    let back = shinobi_proto::quant::dq_pos3(q);
    assert!((back[0] - 2.0 * far).abs() < 0.01 && (back[1] - top).abs() < 0.01, "q_pos3 loses precision");
    let w = world(&l); // every box becomes a collider
    assert_eq!(w.colliders.len(), l.level.boxes.len());
}
